\title{The Sharp Diagonal Correlation Inequality on the Discrete Cube}
\author{Aristotle}
\date{2026-07-13}

\begin{document}

\begin{abstract}
We study real-valued observables on the discrete cube $\zo^n$ equipped with the
uniform probability measure, and their pairwise covariance
$\Cov(f,g) = \E[fg] - \E[f]\E[g]$. We establish a complete description of the
extremes of correlation. First, we prove the two-sided Harris/FKG correlation
inequality: increasing observables are positively correlated and
oppositely-monotone observables are negatively correlated, both \emph{without}
any nonnegativity hypothesis, obtained from the lattice FKG inequality by a
translation to the nonnegative orthant. Second, we prove a sharp diagonal upper
bound: every pair of $[0,1]$-valued observables satisfies $\Cov(f,g) \le
\tfrac14$, via the variance bound $\Var(f) \le \tfrac14$ and the Cauchy--Schwarz
inequality $\Cov(f,g)^2 \le \Var(f)\Var(g)$. We show this bound is attained, and
identify its unique extremal regime by computing the exact correlation spectrum
of dictatorships: a dictatorship has mean $\tfrac12$ and variance $\tfrac14$; two
dictatorships on the same coordinate realise the extremal covariance $\tfrac14$;
two on distinct coordinates are uncorrelated. Finally, we establish
disjoint-support rigidity: observables depending on complementary coordinate
blocks are exactly uncorrelated, delineating the equality boundary of the
correlation inequality.
\end{abstract}

\maketitle

\section{Introduction}
Correlation inequalities are among the most versatile tools in probability,
combinatorics, and statistical physics. On the discrete cube $\zo^n$ with its
coordinatewise partial order, the Harris inequality---a special case of the
Fortuin--Kasteleyn--Ginibre (FKG) inequality---asserts that increasing events
are positively correlated. This paper complements it with a matching ceiling and
an exact analysis of both extremes, since these structures are the raw material
for stability theorems. The contributions are: (1) a translation-invariant proof
of the two-sided Harris inequality for arbitrary real monotone observables; (2)
a sharp diagonal bound $\Cov(f,g) \le \tfrac14$ for $[0,1]$-valued observables,
shown to be attained; (3) the exact correlation spectrum of dictatorships; and
(4) disjoint-support rigidity characterising the equality boundary.

\section{Setup and definitions}
Throughout, $n$ is a fixed nonnegative integer. The discrete cube $\zo^n$ is the
set of functions $x : \{1,\dots,n\} \to \zo$, endowed with the coordinatewise
partial order ($x \le y$ iff $x_i \le y_i$ for all $i$), with least element the
all-zeros point $\mathbf{0}$. The cube carries the uniform probability measure,
mass $2^{-n}$ per point.

\begin{definition}[Observable and expectation]
An \emph{observable} is a function $f : \zo^n \to \R$. Its \emph{expectation} is
$\E[f] = 2^{-n}\sum_{x \in \zo^n} f(x)$. An observable is \emph{$[0,1]$-valued}
if $0 \le f(x) \le 1$ for all $x$, and an \emph{event} if it is $\zo$-valued.
\end{definition}

\begin{definition}[Covariance and variance]
For observables $f,g$, $\Cov(f,g) = \E[f\cdot g] - \E[f]\E[g]$ and
$\Var(f) = \Cov(f,f)$.
\end{definition}

\begin{definition}[Monotonicity]
An observable $f$ is \emph{increasing} if $x \le y \Rightarrow f(x) \le f(y)$,
and \emph{decreasing} if $x \le y \Rightarrow f(x) \ge f(y)$.
\end{definition}

\begin{definition}[Sign coordinates]
For $x \in \zo^n$ let $\chi_i(x) = +1$ if $x_i = 1$ and $-1$ if $x_i = 0$. These
satisfy $\sum_x \chi_i(x) = 0$ for every $i$, and $\sum_x \chi_i(x)\chi_j(x) = 0$
for $i \ne j$.
\end{definition}

\begin{definition}[Dictatorship]
The $i$-th \emph{dictatorship} is the event $\dict_i(x) = x_i$; in sign
coordinates $\dict_i(x) = \tfrac12(\chi_i(x) + 1)$.
\end{definition}

\section{Calculus of expectation and covariance}
\begin{lemma}[Linearity]
$\E[c] = c$, $\E[f+g] = \E[f]+\E[g]$, $\E[cf] = c\E[f]$, $\E[-f] = -\E[f]$, and
$\E$ is monotone: $f \le g$ pointwise implies $\E[f] \le \E[g]$.
\end{lemma}
\begin{proof}
Each identity is the corresponding property of finite sums divided by $2^n$;
$\sum_x c = 2^n c$ handles constants; monotonicity is termwise comparison.
\end{proof}

\begin{lemma}[Covariance algebra]\label{lem:covalg}
$\Cov(f,g) = \Cov(g,f)$; $\Cov(f+c, g) = \Cov(f,g)$ for constant $c$; and
$\Cov(f,-g) = -\Cov(f,g)$.
\end{lemma}
\begin{proof}
Expand the definition. For the shift, $(f+c)g = fg + cg$ gives
$\E[(f+c)g] = \E[fg] + c\E[g]$ while $\E[f+c]\E[g] = (\E[f]+c)\E[g]$; the extra
$c\E[g]$ terms cancel.
\end{proof}

\section{The two-sided Harris/FKG correlation inequality}
\begin{lemma}[Nonnegative Harris]\label{lem:fkgpos}
If $f,g$ are increasing and nonnegative, then $\Cov(f,g) \ge 0$.
\end{lemma}
\begin{proof}
Apply the finite FKG (four-functions) inequality on $\zo^n$ with the constant
weight $\mu \equiv 1$: $2^n \sum_x fg \ge (\sum_x f)(\sum_x g)$. Dividing by
$2^{2n}$ gives $\E[fg] \ge \E[f]\E[g]$.
\end{proof}

\begin{theorem}[Harris inequality, arbitrary sign]\label{thm:harris}
If $f,g$ are increasing, then $\Cov(f,g) \ge 0$.
\end{theorem}
\begin{proof}
Let $\tilde f = f - f(\mathbf 0)$ and $\tilde g = g - g(\mathbf 0)$; both are
increasing and nonnegative (minimum at $\mathbf 0$ is $0$). Lemma~\ref{lem:fkgpos}
gives $\Cov(\tilde f, \tilde g) \ge 0$, and by shift-invariance
(Lemma~\ref{lem:covalg}) $\Cov(\tilde f, \tilde g) = \Cov(f,g)$.
\end{proof}

\begin{theorem}[Reverse correlation inequality]
If $f$ is increasing and $g$ is decreasing, then $\Cov(f,g) \le 0$.
\end{theorem}
\begin{proof}
$-g$ is increasing, so $\Cov(f,-g) \ge 0$ by Theorem~\ref{thm:harris}; and
$\Cov(f,-g) = -\Cov(f,g)$ by Lemma~\ref{lem:covalg}.
\end{proof}

\section{The sharp diagonal upper bound}
\begin{theorem}[Nonnegativity of variance]
For every observable $f$, $\Var(f) \ge 0$.
\end{theorem}
\begin{proof}
With $m = \E[f]$, $\Var(f) = \E[(f-m)^2] = 2^{-n}\sum_x (f(x)-m)^2 \ge 0$.
\end{proof}

\begin{theorem}[Variance bound]\label{thm:varbd}
If $0 \le f(x) \le 1$ for all $x$, then $\Var(f) \le \tfrac14$.
\end{theorem}
\begin{proof}
Since $0 \le f \le 1$, $f^2 \le f$ pointwise, so $\E[f^2] \le \E[f]$. With
$m = \E[f] \in [0,1]$, $\Var(f) = \E[f^2] - m^2 \le m - m^2 = \tfrac14 -
(m-\tfrac12)^2 \le \tfrac14$.
\end{proof}

\begin{theorem}[Cauchy--Schwarz for covariance]\label{thm:cs}
$\Cov(f,g)^2 \le \Var(f)\Var(g)$ for all observables $f,g$.
\end{theorem}
\begin{proof}
Center: $\hat f = f - \E[f]$, $\hat g = g - \E[g]$. Then $\Cov(f,g) =
\E[\hat f\hat g]$, $\Var(f) = \E[\hat f^2]$, $\Var(g) = \E[\hat g^2]$, and the
claim is finite Cauchy--Schwarz divided by $2^{2n}$.
\end{proof}

\begin{theorem}[Sharp diagonal correlation bound]\label{thm:sharp}
If $f,g$ are both $[0,1]$-valued, then $\Cov(f,g) \le \tfrac14$.
\end{theorem}
\begin{proof}
By Theorems~\ref{thm:cs} and~\ref{thm:varbd},
$\Cov(f,g) \le \sqrt{\Var(f)\Var(g)} \le \sqrt{\tfrac14\cdot\tfrac14} = \tfrac14$.
\end{proof}

\section{The correlation spectrum of dictatorships}
\begin{theorem}[Mean of a dictatorship]
$\E[\dict_i] = \tfrac12$ for every $i$.
\end{theorem}
\begin{proof}
$\dict_i = \tfrac12(\chi_i+1)$, so $\E[\dict_i] = \tfrac12\E[\chi_i] + \tfrac12 =
\tfrac12$ since $\E[\chi_i] = 0$.
\end{proof}

\begin{theorem}[Variance of a dictatorship]\label{thm:vardict}
$\Var(\dict_i) = \tfrac14$ for every $i$.
\end{theorem}
\begin{proof}
$\dict_i^2 = \dict_i$, so $\E[\dict_i^2] = \tfrac12$ and $\Var(\dict_i) =
\tfrac12 - \tfrac14 = \tfrac14$.
\end{proof}

\begin{corollary}[Extremiser of the diagonal bound]
$\Cov(\dict_i,\dict_i) = \Var(\dict_i) = \tfrac14$; hence
Theorem~\ref{thm:sharp} is sharp.
\end{corollary}

\begin{theorem}[Distinct dictatorships are uncorrelated]
For $i \ne j$, $\Cov(\dict_i, \dict_j) = 0$.
\end{theorem}
\begin{proof}
$\dict_i\dict_j = \tfrac14(\chi_i\chi_j + \chi_i + \chi_j + 1)$; taking
expectations with $\E[\chi_i]=\E[\chi_j]=0$ and $\E[\chi_i\chi_j]=0$ gives
$\E[\dict_i\dict_j] = \tfrac14$, so $\Cov = \tfrac14 - \tfrac12\cdot\tfrac12 = 0$.
\end{proof}

\section{Disjoint-support rigidity}
Fix a coordinate set $S$. Say $f$ \emph{depends only on $S$} if $f(x)=f(y)$
whenever $x,y$ agree on $S$, and $g$ \emph{depends only on the complement of $S$}
if $g(x)=g(y)$ whenever $x,y$ agree off $S$.

\begin{definition}[Block mask and swap]
For $u,v \in \zo^n$, $\mask_S(u,v)$ is equal to $u$ on $S$ and to $v$ off $S$. On
$\zo^n \times \zo^n$, $\sigma(x,y) = (\mask_S(x,y), \mask_S(y,x))$.
\end{definition}

\begin{lemma}[The swap is an involution]\label{lem:inv}
$\sigma \circ \sigma = \mathrm{id}$, so $\sigma$ is a bijection of the product
cube.
\end{lemma}
\begin{proof}
Coordinatewise, in each case $i \in S$ and $i \notin S$, applying $\sigma$ twice
restores the original.
\end{proof}

\begin{theorem}[Disjoint-support rigidity]
If $f$ depends only on $S$ and $g$ depends only on the complement of $S$, then
$\Cov(f,g) = 0$.
\end{theorem}
\begin{proof}
We prove $(\sum_x f)(\sum_x g) = 2^n \sum_x fg$; dividing by $2^{2n}$ gives
$\E[f]\E[g] = \E[fg]$. Expand as a double sum and use that
$f(x) = f(\mask_S(x,y))$ and $g(y) = g(\mask_S(x,y))$:
\[
\Big(\sum_x f(x)\Big)\Big(\sum_y g(y)\Big)
= \sum_{(x,y)} f(x)g(y)
= \sum_{(x,y)} f(\mask_S(x,y))\,g(\mask_S(x,y)).
\]
Reindexing by the involution $\sigma$ (Lemma~\ref{lem:inv}) and collapsing the
free second coordinate (ranging over all $2^n$ points) gives $2^n\sum_w f(w)g(w)$.
\end{proof}

\section{Discussion and future directions}
On the floor, monotone observables satisfy $\Cov(f,g) \ge 0$, with equality when
supports are disjoint. On the ceiling, $[0,1]$-valued observables satisfy
$\Cov(f,g) \le \tfrac14$, attained by a common dictatorship. Two features of the
proofs: the lower bound uses order while the upper bound uses only boundedness;
and the skeleton is measure-agnostic, with only the single-coordinate variance
input depending on the uniform measure.

\begin{conjecture}[Stability of the diagonal bound]
There is $c > 0$ such that for events $f,g$ with $\E[f]=\E[g]=\tfrac12$ and
$\Cov(f,g) \ge \tfrac14 - \varepsilon$, both agree with a common dictatorship off
a $c\varepsilon$ fraction of the cube.
\end{conjecture}

\begin{conjecture}[Trichotomy at the boundary]
For increasing events $f,g$, $\Cov(f,g) = 0$ iff, after permuting coordinates,
$f$ and $g$ depend on disjoint coordinate blocks.
\end{conjecture}

\begin{conjecture}[Biased measures]
Under the $p$-biased product measure, $\Cov_p(f,g) \le p(1-p)$ for $[0,1]$-valued
observables, attained by a common dictatorship.
\end{conjecture}

\begin{conjecture}[Second-level gap]
If $\Cov(f,\dict_i) \le \varepsilon$ for all $i$ and $f$ is $[0,1]$-valued, then
$\Var(f) \le C\varepsilon$.
\end{conjecture}

