"""Exact correlation spectrum of dictatorships on {0,1}^n."""
from __future__ import annotations
from itertools import product
from typing import Callable, List, Tuple

Point = Tuple[int, ...]

def expectation(f: Callable[[Point], float], n: int) -> float:
    pts = list(product((0, 1), repeat=n))
    return sum(f(x) for x in pts) / len(pts)

def covariance(f: Callable[[Point], float], g: Callable[[Point], float], n: int) -> float:
    ef, eg = expectation(f, n), expectation(g, n)
    return expectation(lambda x: f(x) * g(x), n) - ef * eg

def dict_obs(i: int) -> Callable[[Point], float]:
    return lambda x: float(x[i])

def spectrum(n: int) -> None:
    for i in range(n):
        print(f"E[dict_{i}] = {expectation(dict_obs(i), n):.4f}",
              f"Var[dict_{i}] = {covariance(dict_obs(i), dict_obs(i), n):.4f}")
    print("same-coordinate  Cov =", covariance(dict_obs(0), dict_obs(0), n))
    print("distinct-coord.  Cov =", covariance(dict_obs(0), dict_obs(1), n))

if __name__ == "__main__":
    spectrum(5)

"""Biased-measure exploration: the ceiling deforms to p(1-p)."""
from __future__ import annotations
from itertools import product
from typing import Callable, List, Tuple

Point = Tuple[int, ...]

def weight(x: Point, p: float) -> float:
    return p ** sum(x) * (1 - p) ** (len(x) - sum(x))

def biased_cov(f: Callable[[Point], float], g: Callable[[Point], float],
               n: int, p: float) -> float:
    pts = list(product((0, 1), repeat=n))
    ef = sum(weight(x, p) * f(x) for x in pts)
    eg = sum(weight(x, p) * g(x) for x in pts)
    efg = sum(weight(x, p) * f(x) * g(x) for x in pts)
    return efg - ef * eg

def dict_obs(i: int) -> Callable[[Point], float]:
    return lambda x: float(x[i])

if __name__ == "__main__":
    n = 4
    for p in (0.1, 0.3, 0.5, 0.7, 0.9):
        c = biased_cov(dict_obs(0), dict_obs(0), n, p)
        print(f"p={p:.1f}: Cov_p(dict_0,dict_0) = {c:.4f}  vs p(1-p) = {p*(1-p):.4f}")
